mapper.insert:
INSERT INTO SMT_AUTH_DIRECT_CLAIM
  (ID,DEVICE_ID,KEY_KIND,KEY_VALUE,SUBJECT_TYPE,SUBJECT_ID,PARK_ID,INSTANCE_ID,RESOURCE_ID,WIRE_HASH,FIRST_PHASE_ID,PROOF_KIND,CREATE_TIME)
  SELECT #{id},#{deviceId},#{keyKind},#{keyValue},#{subjectType},#{subjectId},#{parkId},#{instanceId},#{resourceId},#{wireHash},#{firstPhaseId},#{proofKind},#{createTime,jdbcType=TIMESTAMP}
  FROM SMT_AUTH_TRANSPORT_PHASE P WHERE P.ID=#{firstPhaseId} AND P.ACCESS_TYPE='DIRECT' AND P.PHASE='DIRECT_SEND'
   AND P.STATE IN ('PREPARED','INTENT','UNKNOWN','ACCEPTED','FINISHED') AND P.DEVICE_ID=#{deviceId}
   AND P.SUBJECT_TYPE=#{subjectType} AND P.SUBJECT_ID=#{subjectId} AND P.PARK_ID=#{parkId}
   AND P.INSTANCE_ID=#{instanceId} AND P.RESOURCE_ID=#{resourceId}
